import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // --- Plane with sprite texture ---
  const sourceRect = config.intent?.visualSpec?.atlasRegion?.sourceRect || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = sourceRect.w / sourceRect.h;
  const planeW = 2;
  const planeH = planeW / aspect;
  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load the sprite atlas (texture)
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // If the texture is an atlas wider/taller than source rect, set offset & repeat
    // For simplicity assume the image is exactly the source rect
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text "Journal" ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const journalItem = textItems.find((t) => t.text === 'Journal');
  if (journalItem) {
    const textOpts = {
      fontSize: journalItem.typography?.fontSize ?? 96,
      color: '#e8ecf2',           // paper
      align: 'center',
    };
    const textObj = ctx.fontAtlas.createText('Journal', textOpts);
    textObj.position.z = 0.02;   // lift off plane to avoid z-fighting
    // Scale the text to fit the plane width (approximate)
    const textScale = planeW / 6;  // heuristic: 6 units width for 96px text
    textObj.scale.set(textScale, textScale, textScale);
    group.add(textObj);
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // Recursively dispose text child geometries & materials
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    // Kill any GSAP timelines (none here)
  };

  return group;
}
